{
  "findings": [
    {
      "check_id": "AVD-AWS-0026",
      "title": "EBS volume is not encrypted",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "HIGH",
      "explanation": "The volume explicitly sets encrypted to false, leaving all data stored on it unencrypted at rest."
    },
    {
      "check_id": "CKV_AWS_3",
      "title": "EBS volume data is not securely encrypted",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The EBS volume has encryption disabled, which could expose its stored data if the underlying volume or a snapshot is compromised."
    },
    {
      "check_id": "CKV_AWS_189",
      "title": "EBS volume is not encrypted with a customer-managed KMS key",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The volume is neither encrypted nor configured with a customer-managed KMS key, preventing fine-grained control over cryptographic access."
    },
    {
      "check_id": "AVD-AWS-0027",
      "title": "EBS volume does not use a customer-managed KMS key",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "LOW",
      "explanation": "No customer-managed KMS key is associated with the volume, limiting control over key rotation, permissions, and lifecycle."
    }
  ],
  "patched_code": "resource \"aws_kms_key\" \"changeme_ebs_key\" {\n  description             = \"Customer-managed key for EBS volume encryption\"\n  enable_key_rotation     = true\n  deletion_window_in_days = 30\n}\n\nresource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n  kms_key_id        = aws_kms_key.changeme_ebs_key.arn\n}\n",
  "fix_summary": "Enabled encryption for the EBS volume and added a customer-managed KMS key with automatic key rotation. The volume now explicitly uses that key for encryption at rest."
}
